import json
import os
import shutil

from ..utils.logger import logger
from .enb import EnbUtil as enb


class TestLine:
    __test__ = False

    COMMISSIONING_RESULTS_PATH = "/opt/ute/{}_uca_result.json".format(
        os.getenv("CM_RESERVATION_ID")
    )

    def __init__(self, env, dirs):
        self._env = env
        self._dirs = dirs
        self.bts_sw_version, self.secondary_versions = None, None
        self.simulators_versions = {}

    def enable_ssh_rnd_ports(self):
        """Enabling SSH & RND ports for test line"""
        if not self._env.dcm_build:
            enb.enable_ssh_rnd_ports(self._env.product_type)

    def download_config_files(self):
        """Downloading test line config"""
        if not self._env.dcm_build:
            bts_file_collector = enb.create_file_collector(self._env.product_type)
            bts_file_collector.download_config_files(self._dirs.subdir_path)

    def get_software_version(self):
        """Getting test line software version"""
        self.bts_sw_version, self.secondary_versions = self._calculate_bts_sw_versions()

    def set_simulators_versions_using_commissioning_results(self):
        """Getting simulators software versions from commissioning results ($CM_RESERVATION_ID_uca_result.json)
        prepared by commissioning agent and stored on UTE VM under /opt/ute path"""
        simulators = ["iphy", "airphone", "cus", "rtg"]
        self.simulators_versions = (
            self._set_simulators_versions_using_commissioning_results(simulators)
            if self._cm_regression_running()
            else self._fill_simulators_versions_with_empty_versions(simulators)
        )

    def _calculate_bts_sw_versions(self):
        sw_version = self._get_main_sw_version()
        secondary_versions = (
            self._get_secondary_sw_versions(sw_version) if sw_version else []
        )
        return sw_version, secondary_versions

    def _get_main_sw_version(self):
        if self._env.sw_version:
            return self._env.sw_version
        if self._env.no_config or self._env.dcm_build:
            return ""
        else:
            return self._get_sw_version_from_bts()

    def _get_sw_version_from_bts(self):
        bts_file_collector = enb.create_file_collector(self._env.product_type)
        bts_version = bts_file_collector.find_sw_version(
            self._dirs.subdir_path, self._env.load_prefix
        )
        if not bts_version:
            self._dirs.clean_sub_dir()
            self._dirs.move_to_created_sub_dir(self._dirs.backup_dir)
            bts_version = bts_file_collector.find_sw_version(
                self._dirs.subdir_path, self._env.load_prefix
            )
        return bts_version

    def _get_secondary_sw_versions(self, sw_version):
        params_path = "/home/ute/.cache/agents_params.json"
        secondary_builds = []
        if os.path.exists(params_path):
            with open(params_path) as json_file:
                params_serialized = json.load(json_file)
            shutil.rmtree(params_path, ignore_errors=True)
            secondary_builds = [
                build for build in params_serialized["BUILDS"] if build != sw_version
            ]
        return secondary_builds

    def _set_simulators_versions_using_commissioning_results(self, simulators):
        def file_in_wrong_format(s, res):
            return s not in res or "version" not in res[s]

        try:
            with open(self.COMMISSIONING_RESULTS_PATH) as uca_results:
                results = json.load(uca_results)
                for sim in simulators:
                    if file_in_wrong_format(sim, results):
                        results[sim] = {"version": ""}
                return results
        except (IOError, OSError):
            return self._fill_simulators_versions_with_empty_versions(simulators)

    def _cm_regression_running(self):
        return "CM_EXECUTION_ID" in os.environ

    def _fill_simulators_versions_with_empty_versions(self, simulators):
        return dict.fromkeys(simulators, {"version": ""})

    def configure_test_line(self):
        if not self._env.no_config:
            try:
                warning = """
                Fetching data from BTS and R&D ports enabling via SSH is deprecated!
                Functionality will be removed in next MAJOR version!
                Please collect all necessary data beforehand/use --sw_version CLI flag!
                """
                logger.warning(warning)
                self.enable_ssh_rnd_ports()
                self.download_config_files()
                self.get_software_version()
            except Exception as e:
                logger.info(
                    """If you don't need BTS data collection and
                       don't want to see this message please use -nc flag in CLI command"""
                )
                logger.type_of_error_info(e)

        else:
            self.get_software_version()

        self.set_simulators_versions_using_commissioning_results()
